sysevent_script_action.script:
// current: GlideRecord - event scheduled on behalf of (incident for example) 
// event: GlideRecord - sysevent that caused this to be invoked

queueNextImport(
	current /* New file is parked here */,
	event.parm1 /* New file */);

function queueNextImport(current, attachment_sys_id) {
    // Move the attachment to a new data source, and set
	// up a run-once import.

    // Create a new Data Source, "Vendor Data YYYYMMDD HHMMSS"
    var gr_ds = new GlideRecord("sys_data_source");
    gr_ds.setValue("type", "File");
    gr_ds.setValue("format", "Excel");
    gr_ds.setValue("file_retrieval_method", "Attachment");
    gr_ds.setValue("import_set_table_name", "x_42999_import_v_0_vendor_hardware_rows");
    gr_ds.setValue("import_set_table_label", "Vendor Data Rows");
    gr_ds.setValue("sheet_number", "1");
    gr_ds.setValue("header_row", "0");

    var gdt = new GlideDateTime();
    var data_source_name = "Vendor Data " + gdt.getDisplayValueInternal();
    gr_ds.setValue("name", data_source_name);
    var ds_sys_id = gr_ds.update();

    // copy the attachment to the new 
    // Data Source created above, and delete the original
    var gsa = new GlideSysAttachment();
    gsa.copy(
        "sys_data_source",
        current.getValue("sys_id"),
        "sys_data_source",
        ds_sys_id
    );

	gsa.deleteAttachment(attachment_sys_id);

    // Create a new Scheduled Data Import (scheduled_import_set), 
    var gr_sis = new GlideRecord("scheduled_import_set");
    gr_sis.initialize();
    gr_sis.setValue("active", true);
    gr_sis.setValue("data_source", ds_sys_id);
    gr_sis.setValue("name", data_source_name);
    gr_sis.setValue("run_type", "once");

    // run 5 seconds from now
    gdt = new GlideDateTime();
    gdt.addSeconds(5);
    gr_sis.setValue("run_start", gdt);
    gr_sis.update();
}
